INSERT INTO "library_manuals" ("discipline", "title", "specialty", "course", "semester", "authors", "annotation", "status", "draft", "published", "draft_changed", "updated_by", "created_at", "updated_at", "published_at")
SELECT 'Сестринское дело', 'Методика сестринского наблюдения и ухода при заболеваниях органов кровообращения', 'Сестринское дело', 0, 0, 'Кафедра сестринского дела с курсом социальных дисциплин', 'Выжимка из учебного пособия «Общий уход за больными в терапевтической клинике» (гл. 13 и смежные главы) с акцентом на методику: исследование пульса, измерение АД, учёт водного баланса, доврачебная помощь при неотложных состояниях, СЛР, диеты, транспортировка и подготовка к исследованиям — с оснащением, алгоритмами, типичными ошибками, ситуационными задачами и самоконтролем.', 2, j, j, false, 'Кафедра сестринского дела', now(), now(), now()
FROM (SELECT $json${"sections":[{"id":"mtd-s00","title":"Методические указания","blocks":[{"id":"mtd-001","text":{"text":"Выжимка из учебного пособия «Общий уход за больными в терапевтической клинике», гл. 13 «Наблюдение и уход за больными с заболеваниями органов кровообращения» (с. 153–161), с дополнениями из глав о диетах (гл. 4), исследованиях (гл. 10), транспортировке (гл. 2), пожилых (гл. 16) и реанимации (гл. 17). Акцент — на **методике**: что и в каком порядке делает медсестра, зачем нужен каждый шаг и как оценить результат."}},{"id":"mtd-002","heading":{"text":"Цель занятия","level":2}},{"id":"mtd-003","text":{"text":"Освоить методику сестринского наблюдения за пациентами с заболеваниями органов кровообращения и алгоритмы доврачебной помощи при неотложных состояниях."}},{"id":"mtd-004","heading":{"text":"Студент должен","level":2}},{"id":"mtd-005","text":{"text":"**Знать:** свойства пульса, понятия систолического, диастолического и пульсового АД, классификацию уровней АД; симптомы заболеваний ССС; признаки острой сердечной и сосудистой недостаточности; лечебные диеты № 10, 10а, 10с, 10и; признаки клинической и биологической смерти.\n\n**Уметь:**\n- исследовать пульс на лучевой и сонной артериях и описать его свойства;\n- измерить АД методом Короткова, соблюдая правила;\n- организовать учёт водного баланса и оценить его;\n- оказать доврачебную помощь при боли в сердце, гипертоническом кризе, гипотензии, сердечной астме, отёке лёгких, обмороке, коллапсе;\n- провести базовую сердечно-лёгочную реанимацию;\n- подготовить пациента к рентгенологическому исследованию, ангиокардиографии, ЭхоКГ и транспортировать его."}},{"id":"mtd-006","heading":{"text":"Структура каждой манипуляции","level":2}},{"id":"mtd-007","text":{"text":"Каждая манипуляция в методичке разобрана по одной схеме — так её и надо отвечать на занятии и зачёте:"}},{"id":"mtd-008","checklist":{"title":"Схема ответа по манипуляции","ordered":true,"steps":["Цель — зачем выполняют.","Показания и, если есть, противопоказания.","Оснащение.","Подготовка пациента: объяснить ход и получить согласие, правильно уложить или усадить.","Алгоритм выполнения — по шагам, с обоснованием.","Оценка результата и регистрация (температурный лист, лист учёта).","Типичные ошибки и как их избежать."]}},{"id":"mtd-009","callout":{"tone":"MANUAL_CALLOUT_TONE_INFO","title":"Общие и специальные мероприятия","text":"Наблюдение и уход идут в двух направлениях:\n\n- **общие** — нужны любому больному: наблюдение за состоянием, термометрия, контроль пульса и АД, температурный лист, личная гигиена, подача судна;\n- **специальные** — помощь при боли в области сердца, острой и хронической сердечной недостаточности, отёках, нарушениях ритма."}},{"id":"mtd-010","glossary":{"terms":[{"term":"Артериальный пульс","definition":"Периодические колебания стенок артерий из-за изменения их кровенаполнения при работе сердца (лат. pulsus — удар, толчок)."},{"term":"Дефицит пульса","definition":"Разница между ЧСС при аускультации и частотой пульса на лучевой артерии; бывает при мерцательной аритмии."},{"term":"Систолическое АД","definition":"Максимальное давление, возникает вслед за систолой левого желудочка."},{"term":"Диастолическое АД","definition":"Давление, которое поддерживается тонусом артерий в диастолу."},{"term":"Пульсовое давление","definition":"Разница между систолическим и диастолическим АД."},{"term":"Ортопноэ","definition":"Вынужденное положение сидя с опущенными ногами при одышке и удушье: малый круг разгружается."},{"term":"Водный баланс","definition":"Соотношение выпитой и введённой жидкости и выделенной мочи за сутки."},{"term":"Коллапс","definition":"Острая сосудистая недостаточность с падением сосудистого тонуса, снижением сократимости сердца, ОЦК и АД."},{"term":"Обморок (синкопе)","definition":"Кратковременная потеря сознания из-за острой недостаточности кровоснабжения мозга."}]}}]},{"id":"mtd-s01","title":"Методика исследования пульса","blocks":[{"id":"mtd-011","text":{"text":"Пульс исследуют у каждого пациента при поступлении и далее ежедневно. Норма у взрослого — **60–90 в минуту**; менее 60 — редкий пульс, более 90 — частый."}},{"id":"mtd-012","table":{"caption":"Исследование пульса: цель, оснащение, место","header":true,"rows":[{"cells":["Этап","Содержание"]},{"cells":["Цель","Определить свойства пульса: ритм, частоту, наполнение, напряжение, величину, форму"]},{"cells":["Оснащение","Часы с секундной стрелкой или секундомер, температурный лист, красная ручка"]},{"cells":["Место","Лучевая артерия — между шиловидным отростком лучевой кости и сухожилием внутренней лучевой мышцы; при тяжёлом состоянии — сонная артерия; при подозрении на облитерирующее поражение ног — бедренные, подколенные артерии и сосуды стопы"]}]}},{"id":"mtd-013","checklist":{"title":"Алгоритм: пульс на лучевой артерии","ordered":true,"steps":["Объяснить пациенту ход исследования, усадить или уложить; рука расслаблена, кисть и предплечье не на весу.","Одновременно охватить оба запястья так, чтобы подушечки указательного и среднего пальцев лежали на проекции лучевой артерии.","Прижимать артерию к кости с разной силой — пульсовая волна ощущается как расширение и спадение артерии.","Сравнить пульс на обеих руках; если он одинаков (симметричен), дальше исследовать на одной руке.","Определить ритм: равны ли интервалы между пульсовыми волнами.","Подсчитать частоту: при ритмичном пульсе — 15 с и умножить на 4; при аритмии — полную минуту.","Оценить наполнение, напряжение, величину и форму пульса.","Записать результат в температурный лист красными точками по шкале пульса."]}},{"id":"mtd-014","checklist":{"title":"Алгоритм: пульс на сонной артерии (тяжёлое состояние)","ordered":true,"steps":["Найти щитовидный хрящ (кадык).","Сместить указательный и средний пальцы кнаружи — в ямку между хрящом и грудино-ключично-сосцевидной мышцей.","Нащупать пульсацию, не пережимая артерию.","Исследовать только с одной стороны."]}},{"id":"mtd-015","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Осторожно: рефлексогенная зона","text":"Сонную артерию нельзя пережимать и нельзя исследовать с двух сторон одновременно: раздражение каротидного синуса может вызвать резкое урежение ЧСС вплоть до потери сознания."}},{"id":"mtd-016","heading":{"text":"Оценка свойств пульса","level":2}},{"id":"mtd-017","table":{"caption":"Свойства пульса","header":true,"rows":[{"cells":["Свойство","Чем определяется","Варианты"]},{"cells":["Ритмичность","Равенство интервалов между волнами","Ритмичный (p. regularis), аритмичный (p. irregularis)"]},{"cells":["Частота","Число волн в минуту","Норма 60–90; < 60 — редкий, > 90 — частый"]},{"cells":["Наполнение","Объём крови в артерии (систолический объём)","Полный (p. plenus), пустой (p. vacuus), нитевидный (p. filiformis) — сразу сообщить врачу"]},{"cells":["Напряжение","Сила, нужная для полного пережатия артерии; ориентир уровня АД","Удовлетворительного напряжения; твёрдый (p. durus) — при высоком АД; мягкий (p. mollis) — при низком"]},{"cells":["Величина","Наполнение + напряжение, амплитуда колебания стенки","Большой (p. magnus), малый (p. parvus)"]},{"cells":["Форма","Скорость изменения объёма артерии","Скорый (p. celer) — недостаточность аортального клапана, нервное возбуждение; медленный (p. tardus) — аортальный стеноз"]}]}},{"id":"mtd-018","callout":{"tone":"MANUAL_CALLOUT_TONE_CLINICAL","title":"Дефицит пульса","text":"При мерцательной аритмии часть сокращений сердца не даёт пульсовой волны. Методика: одна медсестра выслушивает сердце, другая одновременно считает пульс на лучевой артерии, оба — ровно 1 минуту. Пример: ЧСС при аускультации 98, пульс 78 → дефицит пульса 20."}},{"id":"mtd-019","heading":{"text":"От чего зависит частота пульса","level":2}},{"id":"mtd-020","text":{"text":"- самый частый пульс — у новорождённых; у женщин чаще, чем у мужчин; реже — у спортсменов и пожилых;\n- учащается стоя, при физической нагрузке, лихорадке, сердечной недостаточности, аритмиях;\n- неодинаковый пульс на руках — при аномалиях, сужении или сдавлении лучевой, плечевой или подключичной артерии; работу сердца тогда оценивают по руке, где пульс лучше."}},{"id":"mtd-021","heading":{"text":"Типичные ошибки","level":2}},{"id":"mtd-022","text":{"text":"- пульс нащупывают одним пальцем или большим пальцем (он сам пульсирует);\n- не сравнивают пульс на двух руках;\n- при аритмии считают 15 секунд и умножают — частота получается неверной;\n- сильно пережимают артерию — волна пропадает."}}]},{"id":"mtd-s02","title":"Методика измерения артериального давления","blocks":[{"id":"mtd-023","text":{"text":"Метод — непрямой аускультативный метод Н.С. Короткова (1905) с помощью сфигмоманометра (тонометра). АД зависит от сердечного выброса, общего периферического сопротивления, ОЦК и ЧСС."}},{"id":"mtd-024","table":{"caption":"Измерение АД: цель, оснащение, положение","header":true,"rows":[{"cells":["Этап","Содержание"]},{"cells":["Цель","Определить систолическое и диастолическое АД, оценить состояние ССС и эффект лечения"]},{"cells":["Оснащение","Тонометр с манжетой по размеру руки, фонендоскоп, температурный лист, красная ручка, спиртовые салфетки для мембраны фонендоскопа"]},{"cells":["Положение пациента","Лёжа или сидя на стуле с прямой спинкой, ноги не скрещены, рука на столе ладонью вверх"]}]}},{"id":"mtd-025","heading":{"text":"Правила измерения","level":2}},{"id":"mtd-026","checklist":{"title":"Условия, без которых результат недостоверен","ordered":false,"steps":["Измерять через 1–2 ч после еды и не ранее 1 ч после кофе и курения.","Пациент сидит с опорой на спинку, ноги не скрещены; рука лежит на столе — если рука на весу, АД растёт из-за изометрического сокращения мышц.","Манжета охватывает не менее 80% окружности и 2/3 длины плеча.","Середина манжеты — на уровне сердца (≈ IV межреберье).","Не менее 3 измерений с интервалом не менее 5 минут; берут среднее двух последних."]}},{"id":"mtd-027","checklist":{"title":"Алгоритм измерения АД","ordered":true,"steps":["Объяснить пациенту ход измерения; пациент лёжа или сидя, рука свободно лежит ладонью вверх.","Наложить манжету на плечо на уровне сердца: нижний край на 2–2,5 см выше локтевого сгиба, под манжету проходит один палец, середина баллона — над плечевой артерией.","Соединить трубку манжеты с манометром, проверить положение стрелки на нуле.","Пальцами левой руки нащупать пульс на плечевой артерии в локтевой ямке; быстро накачать воздух и заметить уровень, при котором пульсация исчезла.","Выпустить воздух, поставить фонендоскоп в локтевую ямку над плечевой артерией, не прижимая сильно.","Быстро накачать воздух на 20–30 мм рт. ст. выше уровня исчезновения пульса.","Спускать воздух со скоростью 2 мм рт. ст. в секунду, выслушивая артерию.","Появление первых тонов Короткова — систолическое АД; исчезновение тонов — диастолическое АД.","Выпустить весь воздух, разъединить трубки, снять манжету; обработать мембрану фонендоскопа.","Записать результат в температурный лист красными столбиками; значение округлить до ближайших 2 мм рт. ст."]}},{"id":"mtd-028","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Почему именно так","text":"- **Сначала по пульсу**, потом с фонендоскопом — чтобы не пропустить «аускультативный провал» и не занизить систолическое АД.\n- **Быстрое нагнетание**: медленное нарушает венозный отток, вызывает боль и «смазывает» тоны.\n- **2 мм рт. ст./с**: медленнее — занижение АД.\n- **Уровень сердца**: смещение манжеты на 1 см меняет АД на 0,8 мм рт. ст. (ниже сердца — завышение, выше — занижение)."}},{"id":"mtd-029","heading":{"text":"АД на ногах","level":2}},{"id":"mtd-030","text":{"text":"Измеряют, например, при подозрении на коарктацию аорты. Пациент лежит на животе, манжету накладывают на бедро, тоны выслушивают в подколенной ямке. У взрослых АД в бедренной артерии в норме существенно не отличается от плечевой."}},{"id":"mtd-031","heading":{"text":"Оценка результата","level":2}},{"id":"mtd-032","text":{"text":"Повышенным считают АД от **140/90** (артериальная гипертензия), пониженным — ниже **100/60** (гипотензия). Если систолическое и диастолическое попадают в разные категории, ставят более высокую."}},{"id":"mtd-033","table":{"caption":"Табл. 13-1. Классификация уровней АД у взрослых старше 18 лет (ВОЗ, МОАГ, ДАГ-1; 2001)","header":true,"rows":[{"cells":["Категория","Систолическое, мм рт. ст.","Диастолическое, мм рт. ст."]},{"cells":["Оптимальное","< 120","< 80"]},{"cells":["Нормальное","< 130","< 85"]},{"cells":["Повышенное нормальное","130–139","85–89"]},{"cells":["АГ 1-й степени","140–159","90–99"]},{"cells":["АГ 2-й степени","160–179","100–109"]},{"cells":["АГ 3-й степени","≥ 180","≥ 110"]},{"cells":["Изолированная систолическая АГ","≥ 140","< 90"]}]}},{"id":"mtd-034","callout":{"tone":"MANUAL_CALLOUT_TONE_INFO","title":"Суточное мониторирование АД (СМАД)","text":"Автоматическая манжета на плече измеряет АД каждые 15 мин днём и 30 мин ночью. Норма: днём 135/85, ночью 120/70 (ночное снижение на 10–20%). АГ — при среднесуточном ≥ 135/85, дневном ≥ 140/90, ночном ≥ 125/75. Медсестра объясняет пациенту: во время измерения рука неподвижна и опущена вдоль тела, вести дневник активности и сна."}},{"id":"mtd-035","heading":{"text":"Типичные ошибки","level":2}},{"id":"mtd-036","table":{"caption":"Ошибки при измерении АД","header":true,"rows":[{"cells":["Ошибка","Что получится"]},{"cells":["Узкая манжета (или манжета для взрослых у ребёнка — наоборот)","Узкая завышает, широкая занижает АД"]},{"cells":["Манжета ниже уровня сердца","Завышение"]},{"cells":["Манжета выше уровня сердца","Занижение"]},{"cells":["Слишком медленный выпуск воздуха","Занижение"]},{"cells":["Медленное нагнетание","Боль, нарушение венозного оттока, тоны «смазаны»"]},{"cells":["Рука на весу, ноги скрещены, разговор во время измерения","Завышение"]},{"cells":["Одно измерение вместо трёх","Случайный результат"]}]}}]},{"id":"mtd-s03","title":"Методика учёта водного баланса","blocks":[{"id":"mtd-037","text":{"text":"Отёки при сердечной недостаточности — результат застоя в большом круге и задержки жидкости. На ранних стадиях они **скрытые**: заметны только по быстрой прибавке массы тела и снижению диуреза. Поэтому пациентам с СН ежедневно контролируют водный баланс и взвешивают их."}},{"id":"mtd-038","table":{"caption":"Учёт водного баланса: цели и оснащение","header":true,"rows":[{"cells":["Этап","Содержание"]},{"cells":["Цели","Выявить скрытые отёки; измерить суточный диурез; оценить эффективность лечения, прежде всего мочегонных"]},{"cells":["Оснащение","Медицинские весы, чистая сухая банка 2–3 л, два градуированных сосуда, лист учёта водного баланса, температурный лист"]}]}},{"id":"mtd-039","checklist":{"title":"Алгоритм учёта водного баланса","ordered":true,"steps":["Накануне предупредить пациента и объяснить правила сбора мочи и записи выпитой жидкости.","Взвесить пациента утром натощак, в одной и той же одежде.","В 6 ч утра разбудить пациента — он мочится в унитаз (или выводят мочу катетером); эту порцию не учитывают.","Все последующие порции до 6 ч следующего утра включительно собирать в банку.","В течение суток учитывать всю поступившую жидкость в мл: выпитую (первые блюда считают как 75% жидкости) и введённую парентерально.","Измерить суточную мочу градуированным сосудом.","Рассчитать баланс и записать результат в лист учёта и температурный лист."]}},{"id":"mtd-040","heading":{"text":"Оценка","level":2}},{"id":"mtd-041","text":{"text":"Суточный диурез в норме 1,5–2 л — это **70–80%** всей потреблённой жидкости.\n\n**Ожидаемый диурез = вся поступившая жидкость × 0,8.**\n\n- выделено меньше расчётного — баланс **отрицательный**: жидкость задерживается, отёки нарастают, диуретики неэффективны;\n- выделено больше — баланс **положительный**: отёки сходят, лечение эффективно."}},{"id":"mtd-042","callout":{"tone":"MANUAL_CALLOUT_TONE_CLINICAL","title":"Пример расчёта","text":"Пациент выпил 1200 мл (с учётом супа), получил 300 мл внутривенно. Поступило 1500 мл, ожидаемый диурез — 1500 × 0,8 = 1200 мл. Выделено 900 мл → баланс отрицательный: сообщить врачу, проверить отёки и массу тела."}},{"id":"mtd-043","heading":{"text":"Уход за пациентом с отёками","level":2}},{"id":"mtd-044","text":{"text":"- у ходячих отёки — на ногах, у лежачих — на крестце, пояснице, лопатках; кожа гладкая, блестящая, от надавливания остаётся долго не расправляющаяся ямка;\n- пациенты на постельном режиме, получающие мочегонные, должны иметь мочеприёмник и судно;\n- в местах отёков (крестец, поясница, лопатки) высок риск трофических нарушений — **особенно важна профилактика пролежней**;\n- при большом асците врач выполняет абдоминальную пункцию; быстрое удаление большого объёма жидкости может вызвать коллапс — медсестра контролирует пульс и АД."}}]},{"id":"mtd-s04","title":"Доврачебная помощь при неотложных состояниях","blocks":[{"id":"mtd-045","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Общее правило","text":"При любом неотложном состоянии медсестра **сначала вызывает врача** (через другого сотрудника, не оставляя пациента), затем придаёт правильное положение, обеспечивает свежий воздух и покой, контролирует пульс, АД и дыхание. Лекарства вводят только по назначению врача."}},{"id":"mtd-046","heading":{"text":"Боль в сердце, стенокардия","level":2}},{"id":"mtd-047","text":{"text":"Типичный приступ провоцируется физической или эмоциональной нагрузкой: давящая, жгучая, сжимающая боль за грудиной со страхом смерти; отдаёт в левое плечо, руку, левую половину шеи, нижнюю челюсть; длится 1–10 мин, проходит в покое или через 1–3 мин после нитроглицерина под язык. Боли не сердечного происхождения (кардиалгия) бывают при сухом плеврите, остеохондрозе, межрёберной невралгии, миозите, грыже пищеводного отверстия диафрагмы."}},{"id":"mtd-048","checklist":{"title":"Помощь при приступе стенокардии","ordered":true,"steps":["Прекратить нагрузку, обеспечить полный покой.","Усадить или уложить с возвышенным изголовьем.","Дать нитроглицерин под язык.","Контролировать пульс и АД, сообщить врачу.","Реже — горчичники на область сердца (по назначению)."]}},{"id":"mtd-049","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Заподозрить инфаркт миокарда","text":"Если боль чрезвычайно сильная, **не снимается покоем и нитроглицерином и длится более 30 мин**, сопровождается страхом смерти, удушьем, резкой слабостью, падением АД — это инфаркт. Срочно врач, госпитализация в палату интенсивной терапии с мониторированием и готовностью к реанимации."}},{"id":"mtd-050","text":{"text":"**Уход при инфаркте миокарда в первые дни** — строгий постельный режим: медсестра следит за постелью и бельём, выполняет все гигиенические процедуры, кормит пациента, подаёт судно и мочеприёмник. Питание — диета № 10и."}},{"id":"mtd-051","heading":{"text":"Гипертонический криз","level":2}},{"id":"mtd-052","text":{"text":"Резкое повышение АД с сильной головной болью, головокружением, тошнотой и рвотой; опасен нарушением мозгового и коронарного кровообращения. При АГ строго соблюдают лечебно-охранительный режим: отрицательные эмоции, нервно-психические нагрузки и плохой сон утяжеляют болезнь."}},{"id":"mtd-053","checklist":{"title":"Помощь при гипертоническом кризе","ordered":true,"steps":["Вызвать врача.","Обеспечить полный покой, возвышенное положение головы.","Обеспечить доступ свежего воздуха.","Горячие ножные ванны, тёплые ванны для рук (37–40 °C).","Контролировать АД и пульс; антигипертензивные препараты — по назначению врача."]}},{"id":"mtd-054","heading":{"text":"Острая артериальная гипотензия","level":2}},{"id":"mtd-055","checklist":{"title":"Помощь при острой гипотензии","ordered":true,"steps":["Уложить пациента горизонтально.","Приподнять ножной конец кровати — улучшается приток крови к мозгу.","Вызвать врача, контролировать АД и пульс; лекарства — по назначению."]}},{"id":"mtd-056","heading":{"text":"Сердечная астма и отёк лёгких","level":2}},{"id":"mtd-057","text":{"text":"**Сердечная астма** — внезапный тяжёлый приступ удушья с шумным дыханием, чаще ночью; пациент садится (ортопноэ). **Отёк лёгких** — самое тяжёлое проявление сердечной недостаточности: к удушью добавляются клокочущее дыхание и розовая пенистая мокрота."}},{"id":"mtd-058","checklist":{"title":"Алгоритм помощи при сердечной астме и отёке лёгких","ordered":true,"steps":["Немедленно вызвать врача.","Усадить пациента с опущенными ногами (ортопноэ); снять стесняющую одежду, открыть окно.","Дать нитроглицерин под язык, если систолическое АД не ниже 100 мм рт. ст.","Начать оксигенотерапию с пеногасителем через маску или носовой катетер.","Отсасывать пенистую мокроту электроотсосом.","Наложить венозные жгуты на обе ноги на 15 см ниже паховой складки (можно и на руки): артериальный пульс ниже жгута сохраняется, конечность синюшная, но не белая.","Через 15–20 мин ослабить жгуты; снимать последовательно и медленно, с одной конечности за другой.","По назначению врача — горячие ножные ванны, кровопускание, внутривенно наркотические анальгетики, мочегонные, ингибиторы АПФ, сердечные гликозиды."]}},{"id":"mtd-059","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Жгуты — венозные, не артериальные","text":"Жгут должен пережимать только вены: если пульс ниже жгута исчез или конечность побелела — жгут затянут слишком сильно, его нужно ослабить. Снимать все жгуты сразу нельзя — кровь вернётся в малый круг, отёк лёгких усилится."}},{"id":"mtd-060","heading":{"text":"Обморок","level":2}},{"id":"mtd-061","text":{"text":"Предвестники: слабость, головокружение, звон в ушах, потемнение в глазах, тошнота, «ватные» ноги. Затем бледность, холодный липкий пот, падение АД, малый нитевидный пульс. Длится обычно 20–30 с; лёжа сознание быстро возвращается. В отличие от эпилепсии непроизвольное мочеиспускание редко, нет остановки дыхания и прикуса языка."}},{"id":"mtd-062","checklist":{"title":"Помощь при обмороке","ordered":true,"steps":["Уложить горизонтально с приподнятыми ногами.","Расстегнуть стесняющую одежду, обеспечить свежий воздух.","Обрызгать лицо и грудь холодной водой, растереть виски.","Осторожно дать вдохнуть пары нашатырного спирта на ватке — рефлекторно активируется дыхательный центр.","Согреть; контролировать пульс и АД, сообщить врачу."]}},{"id":"mtd-063","heading":{"text":"Коллапс","level":2}},{"id":"mtd-064","text":{"text":"Острая сосудистая недостаточность: падение сосудистого тонуса, сократимости сердца, ОЦК и АД. Причины — инфаркт миокарда, кровотечение, обезвоживание при рвоте и диарее, тяжёлые инфекции, передозировка антигипертензивных. Клиника как при обмороке, но сознание теряется не всегда: пациент заторможен, безучастен, зрачки расширены."}},{"id":"mtd-065","checklist":{"title":"Помощь при коллапсе","ordered":true,"steps":["Вызвать врача.","Уложить горизонтально, голова ниже ног (приподнять ножной конец).","Расстегнуть одежду, свежий воздух, кислород; согреть.","Устранить причину, если возможно (например, остановить кровотечение).","Подготовить систему для внутривенной инфузии; по назначению — препараты крови или кровезаменители, средства, повышающие сосудистый тонус."]}},{"id":"mtd-066","table":{"caption":"Положение пациента — главный элемент доврачебной помощи","header":true,"rows":[{"cells":["Состояние","Положение пациента","Почему"]},{"cells":["Сердечная астма, отёк лёгких, одышка","Сидя с опущенными ногами","Кровь депонируется в сосудах ног и живота, малый круг разгружается"]},{"cells":["Стенокардия, гипертонический криз","Полусидя, возвышенное изголовье","Меньше нагрузка на сердце, отток крови от головы"]},{"cells":["Обморок, коллапс, острая гипотензия","Лёжа, ноги приподняты","Улучшается приток крови к мозгу"]}]}}]},{"id":"mtd-s05","title":"Сердечно-лёгочная реанимация","blocks":[{"id":"mtd-067","text":{"text":"Остановка сердца и дыхания — начало клинической смерти; это обратимый этап, в среднем 5–6 мин. Спасение зависит от быстроты и качества первичных мероприятий."}},{"id":"mtd-068","heading":{"text":"Признаки клинической смерти","level":2}},{"id":"mtd-069","text":{"text":"- отсутствие сознания (через 10–15 с после остановки кровообращения) и реакции на раздражители;\n- расширение зрачков без реакции на свет (начинается через 40–60 с);\n- остановка дыхания или агональное дыхание;\n- нет пульса на сонных и бедренных артериях;\n- цианоз губ, пальцев, мочек ушей, бледность с синюшной мраморностью."}},{"id":"mtd-070","text":{"text":"**Биологическую смерть** констатирует врач: максимально расширенные зрачки без реакции, снижение температуры тела, трупные пятна, мышечное окоченение."}},{"id":"mtd-071","checklist":{"title":"Алгоритм базовой СЛР у взрослого (по пособию)","ordered":true,"steps":["Убедиться в отсутствии сознания, дыхания и пульса на сонной артерии; отметить время.","Позвать на помощь, вызвать реанимационную бригаду.","Уложить пациента на жёсткую поверхность (пол).","Восстановить проходимость дыхательных путей: запрокинуть голову (нельзя при травме шейного отдела), выдвинуть нижнюю челюсть, очистить рот и глотку от слизи, рвотных масс, протезов.","Начать непрямой массаж сердца: точка — нижняя треть грудины, на 2 пальца выше мечевидного отростка; основания кистей одна на другой, руки прямые, давление весом тела.","Проводить искусственное дыхание «изо рта в рот» или «изо рта в нос» через марлю, лучше — мешком Амбу.","Чередовать вдохи и компрессии, не прерывая массаж надолго.","Каждые 1–2 мин оценивать эффективность: пульс на сонной артерии при каждом толчке, сужение зрачков, порозовение кожи; экскурсия грудной клетки при вдохе."]}},{"id":"mtd-072","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Цифры пособия устарели — сверяйтесь с действующими рекомендациями","text":"Пособие даёт соотношение 1 вдох : 5 компрессий (2 спасателя) и 2 : 15 (один спасатель), глубину 4–5 см, темп 80–100 в минуту и прекардиальный удар. Действующие рекомендации по СЛР у взрослых (Европейский совет по реанимации, AHA, НСР) — **30 компрессий : 2 вдоха** для одного и двух спасателей, глубина **5–6 см**, темп **100–120 в минуту**, прекардиальный удар рутинно не применяют. На зачёте и на практике отвечайте по действующему стандарту кафедры."}},{"id":"mtd-073","heading":{"text":"Критерии эффективности и осложнения","level":2}},{"id":"mtd-074","text":{"text":"- **ИВЛ эффективна**, если поднимается грудная клетка; вздутие эпигастрия означает, что воздух попал в желудок — риск рвоты и аспирации;\n- **массаж эффективен**, если на сонной или бедренной артерии ощущается пульс при каждом толчке, сужаются зрачки, розовеет кожа;\n- **осложнения**: переломы рёбер и грудины (самое частое), пневмоторакс; давление на мечевидный отросток — разрыв печени; аспирация желудочного содержимого."}}]},{"id":"mtd-s06","title":"Режим, питание, транспортировка, подготовка к исследованиям","blocks":[{"id":"mtd-075","heading":{"text":"Лечебные диеты","level":2}},{"id":"mtd-076","table":{"caption":"Лечебные диеты при болезнях ССС","header":true,"rows":[{"cells":["Диета","Показания","Соль / свободная жидкость","Режим"]},{"cells":["№ 10","Болезни ССС без признаков СН","6–7 г (3–5 г на руки) / 1,2 л","5 раз"]},{"cells":["№ 10а","Выраженная СН","соль исключена / 0,6–0,7 л","6 раз, не более 4 нед"]},{"cells":["№ 10с","Атеросклероз сосудов сердца и мозга, инфаркт в стадии рубцевания, гипертоническая болезнь","8–10 г / 1,2 л","5 раз, на ночь кефир"]},{"cells":["№ 10и","Инфаркт миокарда: три последовательных рациона (1-я нед, 2–3-я нед, 4-я нед)","I: без соли / 0,7–0,8 л; II: 3 г / 0,9–1 л; III: 5–6 г / 1–1,1 л","I–II — 6 раз, III — 5 раз"]}]}},{"id":"mtd-077","text":{"text":"**Задача медсестры** — объяснить пациенту и родственникам смысл диеты и проконтролировать передачи. При диете № 10 исключают: свежий хлеб и сдобу, крепкие бульоны, жирное мясо, копчёности, колбасы, консервы, солёную рыбу и сыры, бобовые, солёные и маринованные овощи, шоколад, острые приправы, натуральный кофе и какао. Полезны продукты с калием — изюм, курага, чернослив, картофель."}},{"id":"mtd-078","callout":{"tone":"MANUAL_CALLOUT_TONE_INFO","title":"Разгрузочные диеты при ХСН","text":"Молочная (диета Карелля) — снятое молоко по 200 мл 4 раза в день в первую неделю; творожная — 500 г творога, 150 г сахара, 1–2 стакана отвара шиповника на 5 приёмов; молочно-картофельная — 1 кг картофеля и 0,5 л молока без соли, 2–6 дней. Назначает врач."}},{"id":"mtd-079","heading":{"text":"Транспортировка","level":2}},{"id":"mtd-080","table":{"caption":"Транспортировка пациентов с заболеваниями ССС","header":true,"rows":[{"cells":["Состояние","Как транспортировать"]},{"cells":["Сердечно-сосудистая недостаточность","Полусидя, хорошо укрыть, грелки к ногам и рукам"]},{"cells":["Острая сосудистая недостаточность","Лёжа, голова ниже уровня ног"]}]}},{"id":"mtd-081","heading":{"text":"Подготовка к исследованиям","level":2}},{"id":"mtd-082","table":{"caption":"Инструментальные исследования ССС","header":true,"rows":[{"cells":["Исследование","Подготовка и роль медсестры"]},{"cells":["ЭКГ","Подготовка не нужна; может сниматься уже в смотровом кабинете приёмного отделения"]},{"cells":["Рентгеноскопия и рентгенография сердца","Подготовка не нужна; взвесь бария контрастирует пищевод — по его смещению судят об увеличении левого предсердия"]},{"cells":["Эхокардиография, допплерография","Подготовка не нужна"]},{"cells":["Ангиокардиография","Фактически операция. Накануне — пробы на переносимость йода и анестетиков; исследование натощак. После — особое наблюдение: при боли в сердце, одышке, нарушении ритма, падении АД, резкой слабости сразу сообщить врачу"]}]}},{"id":"mtd-083","heading":{"text":"Пожилые пациенты","level":2}},{"id":"mtd-084","text":{"text":"- у пожилых повышается главным образом систолическое АД; возрастных нормативов АД нет;\n- сосудистая недостаточность проявляется не классическим коллапсом, а обострением ИБС, инсультом, нарастанием почечной недостаточности — медсестра должна насторожиться при любом резком ухудшении;\n- ухудшение ИБС провоцируют бронхолёгочные болезни, нагрузка, переедание, стресс, инфекции, операции;\n- медсестра объясняет вред курения (учащение сокращений, сужение сосудов, рост АД; смертность от болезней ССС у курильщиков почти вдвое выше), рекомендует дневной отдых, спокойный сон, дыхательную гимнастику и умеренную физкультуру."}}]},{"id":"mtd-s07","title":"Ситуационные задачи","blocks":[{"id":"mtd-085","text":{"text":"Решите задачу письменно по схеме: проблемы пациента → что делает медсестра (по шагам) → обоснование. Затем сверьтесь с эталоном."}},{"id":"mtd-086","clinicalCase":{"title":"Задача 1. Удушье ночью","condition":"Пациент 64 лет с постинфарктным кардиосклерозом ночью проснулся от удушья. Сидит в постели, опустив ноги, дыхание шумное, клокочущее, отходит розовая пенистая мокрота. АД 150/95 мм рт. ст., пульс 112 в минуту.","questions":["Какое неотложное состояние развилось?","Составьте алгоритм доврачебной помощи.","Как правильно наложить и снять венозные жгуты?"],"answer":"**Отёк лёгких** (тяжёлое проявление острой левожелудочковой недостаточности).\n\n1. Немедленно вызвать врача.\n2. Сохранить положение сидя с опущенными ногами, снять стесняющую одежду, открыть окно.\n3. Нитроглицерин под язык — систолическое АД выше 100.\n4. Кислород с пеногасителем через маску или носовой катетер.\n5. Отсасывать пенистую мокроту электроотсосом.\n6. Венозные жгуты на обе ноги на 15 см ниже паховой складки.\n7. Далее — по назначению врача.\n\nЖгуты пережимают только вены: пульс ниже жгута сохраняется, конечность синюшная, но не белая. Через 15–20 мин ослабить; снимать медленно, по одному."}},{"id":"mtd-087","clinicalCase":{"title":"Задача 2. Ошибка при измерении АД","condition":"Студентка измеряет АД пациентке, которая сидит, положив ногу на ногу; рука свисает со стула. Манжета наложена на локтевой сгиб. Студентка медленно накачивает воздух и сразу ставит фонендоскоп. Получено 168/100 мм рт. ст.","questions":["Какие ошибки допущены?","Как они влияют на результат?","Опишите правильную методику."],"answer":"**Ошибки:** скрещённые ноги и рука на весу (завышение АД); манжета на локтевом сгибе, а не на 2–2,5 см выше; медленное нагнетание (боль, нарушение венозного оттока, тоны «смазаны»); не определён уровень исчезновения пульса пальпаторно; одно измерение.\n\n**Правильно:** пациентка сидит с опорой на спинку, ноги не скрещены, рука на столе на уровне сердца; манжета на 2–2,5 см выше локтевого сгиба, под неё проходит палец; сначала пальпаторно найти уровень исчезновения пульса, затем быстро накачать на 20–30 мм выше, спускать по 2 мм рт. ст./с; 3 измерения через 5 мин, среднее двух последних."}},{"id":"mtd-088","clinicalCase":{"title":"Задача 3. Отёки у пациента с ХСН","condition":"Пациент с хронической сердечной недостаточностью получает фуросемид. За сутки выпил 1100 мл жидкости, внутривенно получил 400 мл, выделил 800 мл мочи. За 2 дня масса тела выросла на 1,5 кг. Отёки на голенях, пациент лежачий.","questions":["Рассчитайте водный баланс и оцените его.","Где ещё искать отёки у лежачего пациента?","Какие проблемы ухода возникают и как их решить?"],"answer":"Поступило 1500 мл, ожидаемый диурез 1500 × 0,8 = 1200 мл, выделено 800 мл → **баланс отрицательный**: жидкость задерживается, мочегонная терапия неэффективна — сообщить врачу.\n\nУ лежачих отёки — на крестце, пояснице, лопатках.\n\nПроблемы: риск пролежней в местах отёков — профилактика пролежней (смена положения, уход за кожей); частое мочеиспускание на диуретиках — мочеприёмник и судно у постели; ежедневное взвешивание и учёт водного баланса; диета № 10а (без соли, жидкость 0,6–0,7 л)."}},{"id":"mtd-089","clinicalCase":{"title":"Задача 4. Плохо в процедурном кабинете","condition":"Во время взятия крови из вены пациентка 19 лет побледнела, пожаловалась на звон в ушах и потемнение в глазах, покрылась холодным потом и сползла со стула. Пульс малый, 52 в минуту; через 20 секунд глаза открыла.","questions":["Что произошло?","Чем это состояние отличается от эпилептического припадка?","Алгоритм помощи."],"answer":"**Обморок** (эмоциональный — при виде крови).\n\nВ отличие от эпилепсии: есть предвестники, кратковременность (20–30 с), непроизвольное мочеиспускание редко, нет остановки дыхания и прикуса языка; лёжа сознание быстро возвращается.\n\nПомощь: прекратить процедуру, уложить с приподнятыми ногами; расстегнуть одежду, свежий воздух; обрызгать лицо холодной водой; осторожно дать вдохнуть нашатырный спирт; согреть; контроль пульса и АД; сообщить врачу."}},{"id":"mtd-090","clinicalCase":{"title":"Задача 5. Боль за грудиной","condition":"Пациент 58 лет поднялся по лестнице, после чего возникла сжимающая боль за грудиной, отдающая в левую руку. Нитроглицерин принял 2 раза с интервалом 5 минут, боль не проходит уже 35 минут, пациент покрыт холодным потом, АД 95/60 мм рт. ст.","questions":["Какое состояние можно заподозрить?","Действия медсестры.","Какой режим и диета нужны в первые дни?"],"answer":"Признаки **инфаркта миокарда**: боль более 30 мин, не снимается нитроглицерином, падение АД, холодный пот.\n\nСрочно вызвать врача; полный покой, уложить с приподнятым изголовьем; больше нитроглицерин не давать (АД ниже 100); контроль пульса и АД; подготовиться к записи ЭКГ и транспортировке в палату интенсивной терапии лёжа, готовность к реанимации.\n\nСтрогий постельный режим: медсестра выполняет гигиену, кормит, подаёт судно и мочеприёмник. Диета № 10и, I рацион — протёртая пища без соли, 6 раз в день."}}]},{"id":"mtd-s08","title":"Самоконтроль","blocks":[{"id":"mtd-091","quiz":{"title":"Методика манипуляций","questions":[{"text":"Где пальпируют лучевую артерию?","options":["Между шиловидным отростком лучевой кости и сухожилием внутренней лучевой мышцы","В локтевой ямке","На тыле кисти","Между I и II пястными костями"],"correct":[0],"explanation":"Именно там артерию можно прижать к кости."},{"text":"На какой уровень выше исчезновения пульса накачивают манжету?","options":["На 5–10 мм рт. ст.","На 20–30 мм рт. ст.","На 50–60 мм рт. ст.","До 300 мм рт. ст."],"correct":[1],"explanation":"На 20–30 мм рт. ст. выше уровня исчезновения пульса."},{"text":"Сколько раз измеряют АД, чтобы получить достоверный результат?","options":["Один раз","Не менее 3 раз с интервалом не менее 5 мин","2 раза подряд","Каждый час в течение дня"],"correct":[1],"explanation":"Берут среднее двух последних из трёх измерений."},{"text":"Первая порция мочи в 6 ч утра при учёте водного баланса:","options":["Собирается в банку","Не учитывается","Отправляется на общий анализ","Учитывается вдвое"],"correct":[1],"explanation":"Её выливают; собирают всё последующее до 6 ч следующего утра включительно."},{"text":"Какую долю жидкости содержат первые блюда при учёте выпитого?","options":["50%","75%","100%","25%"],"correct":[1],"explanation":"Первые блюда считают как 75% жидкости."},{"text":"Что из перечисленного — признаки правильно наложенного венозного жгута?","options":["Пульс ниже жгута сохранён","Конечность белая","Конечность синюшная","Пульс ниже жгута исчез"],"correct":[0,2],"explanation":"Венозный жгут пережимает вены, но не артерии: пульс есть, конечность синюшная."}]}},{"id":"mtd-092","quiz":{"title":"Оценка результатов","questions":[{"text":"АД 150/85 мм рт. ст. соответствует:","options":["Нормальному АД","АГ 1-й степени","АГ 2-й степени","Повышенному нормальному"],"correct":[1],"explanation":"Систолическое 140–159 — АГ 1-й степени; ставят более высокую категорию."},{"text":"Пульс твёрдый (p. durus) бывает при:","options":["Низком АД","Высоком АД","Кровопотере","Обмороке"],"correct":[1],"explanation":"Напряжение пульса — ориентир уровня АД."},{"text":"Поступило 2000 мл, выделено 1900 мл мочи. Баланс:","options":["Отрицательный","Положительный","Нельзя оценить"],"correct":[1],"explanation":"Ожидаемый диурез 1600 мл; выделено больше — баланс положительный, отёки сходят."},{"text":"Нитевидный пульс — повод:","options":["Повторить через час","Сразу сообщить врачу","Измерить температуру","Ничего не делать"],"correct":[1],"explanation":"Нитевидный пульс — признак тяжёлого нарушения гемодинамики."}]}}]}]}$json$::jsonb AS j) v
WHERE NOT EXISTS (SELECT 1 FROM "library_manuals" WHERE "discipline" = 'Сестринское дело' AND "title" = 'Методика сестринского наблюдения и ухода при заболеваниях органов кровообращения');
