DELETE FROM "library_manuals" WHERE "discipline" = 'Сестринское дело' AND "updated_by" = 'Кафедра сестринского дела'
  AND "title" IN ('Сердечно-сосудистая система: конспект по трём учебникам', 'Методика сестринского наблюдения и ухода при заболеваниях органов кровообращения');
